from pathlib import Path
import json
r=Path(__file__).resolve().parent
changes=json.loads('{"server/index.mjs": [["   if(p===\'/brand/tharon-group.png\')return staticFile(res,path.join(ROOT,\'site/brand/tharon-group.png\'));", "   // Public layout preview uses newly generated fictional records, never the live store.\\n   if(p===\'/olivia-layout\'||p.startsWith(\'/olivia-layout/\')){\\n    if(req.method!==\'GET\')fail(405,\'Layout preview is read-only.\');\\n    if(p===\'/olivia-layout\'){res.writeHead(302,{Location:\'/olivia-layout/\'});return res.end();}\\n    const asset=p.slice(\'/olivia-layout/\'.length);\\n    if(!asset){const html=readFileSync(path.join(ROOT,\'site/index.html\'),\'utf8\').replace(\'src=\\"bootstrap.js\\"\',\'src=\\"layout-bootstrap.js\\"\').replace(/src=\\"remote\\\\.js[^\\\\\\"]*\\"/,\'src=\\"olivia-preview.js\\"\');res.writeHead(200,{\'Content-Type\':\'text/html; charset=utf-8\'});return res.end(html);}\\n    if(asset===\'layout-bootstrap.js\'){\\n     let state=initialState(false);const tl=engine(state,\'u0\');\\n     for(const [i,rep,building,days,approved,moveIn]of [[1,\'u2\',\'riverside\',2,true,4],[2,\'u1\',\'sierra\',9,false,null],[3,\'u2\',\'crescendo\',16,true,-2],[4,\'u1\',\'shadowridge\',32,false,null]]){\\n      state=execute(state,\'u0\',{op:\'createLead\',createdId:\'L_layout_sample_\'+i,args:[{first:\'Sample\',last:\'Referral \'+i,building,rep,payer:\'Private pay\',notes:\'Fictional referral for layout review only.\'}]});\\n      const l=state.leads.find(l=>l.id===\'L_layout_sample_\'+i);l.programStatus=approved?\'approved\':\'pending\';l.createdAt=tl.addDays(-days)+\'T12:00:00\';l.created=tl.addDays(-days);if(moveIn!==null)l.moveIn=tl.addDays(moveIn);\\n     }\\n     state=scoped(state,\'u2\');state.sample_data=true;state.users=state.users.map(u=>({...u,email:u.id+\'@example.invalid\'}));\\n     const boot={state,csrf:null,mode:\'sample\',preview:true,layoutOnly:true,extractionEnabled:false,voiceEnabled:\'unconfigured\'};\\n     res.writeHead(200,{\'Content-Type\':\'text/javascript\'});return res.end(\'window.TL_BOOT=\'+JSON.stringify(boot).replace(/</g,\'\\\\\\\\u003c\')+\';\');\\n    }\\n    const allowed=new Set([\'styles.css\',\'data.js\',\'roster.js\',\'import-utils.js\',\'pdf-intake.js\',\'capture.js\',\'libertana.js\',\'county-roadmap.js\',\'referral-progress.js\',\'api.js\',\'olivia-preview.js\',\'assistant.js\',\'document-viewer.js\',\'libertana-pdf.js\',\'libertana-ui.js\',\'followup-contacts.js\',\'app.js\',\'vendor/xlsx.full.min.js\',\'brand/tharon-group.png\',\'icons/tharon-symbol-white-favicon.png\',\'icons/tharon-symbol-white-apple.png\',\'og.png\']);\\n    if(!allowed.has(asset))fail(404,\'Not found.\');return staticFile(res,path.join(ROOT,\'site\',asset));\\n   }\\n   if(p===\'/brand/tharon-group.png\')return staticFile(res,path.join(ROOT,\'site/brand/tharon-group.png\'));"]], "site/olivia-preview.js": [["banner.textContent=\'Olivia\\u2019s live view \\u00b7 Preview only \\u00b7 Changes are disabled\';", "banner.textContent=boot.layoutOnly?\'Olivia\\u2019s layout \\u00b7 Sample leads only \\u00b7 No login required\':\'Olivia\\u2019s live view \\u00b7 Preview only \\u00b7 Changes are disabled\';"], ["for(const [label,url]of [[\'Return to my account\',\'/\'],[\'Refresh Olivia\\u2019s view\',\'/olivia-preview\'+location.hash]])", "for(const [label,url]of (boot.layoutOnly?[[\'Refresh layout\',\'/olivia-layout/\'+location.hash]]:[[\'Return to my account\',\'/\'],[\'Refresh Olivia\\u2019s view\',\'/olivia-preview\'+location.hash]]))"]]}')
for name,edits in changes.items():
 p=r/name
 s=p.read_text()
 for before,after in edits:
  if s.count(before)!=1: raise SystemExit(name+": unexpected layout source")
  s=s.replace(before,after,1)
 p.write_text(s)

(r/"test/olivia-layout.test.mjs").write_text('import test from \'node:test\';import assert from \'node:assert/strict\';import {mkdtempSync,rmSync} from \'node:fs\';import {tmpdir} from \'node:os\';import path from \'node:path\';import vm from \'node:vm\';import {createApplication} from \'../server/index.mjs\';import {initialState,execute} from \'../server/engine.mjs\';\ntest(\'public Olivia layout needs no account and never includes records from the live store\',async()=>{const dir=mkdtempSync(path.join(tmpdir(),\'olivia-layout-\')),app=await createApplication({schedule:false,env:{NODE_ENV:\'test\',APP_MODE:\'live\',PHI_APPROVED:\'true\',DATABASE_URL:\'\',SQLITE_PATH:path.join(dir,\'db\')}});await new Promise(r=>app.server.listen(0,\'127.0.0.1\',r));const origin=\'http://127.0.0.1:\'+app.server.address().port,get=p=>fetch(origin+p,{redirect:\'manual\'});try{const state=execute(initialState(false),\'u0\',{op:\'createLead\',createdId:\'L_secret_live_record\',args:[{first:\'PrivateLiveSentinel\',last:\'NeverPublic\',rep:\'u2\',building:\'riverside\'}]});await app.store.query(\'UPDATE app_state SET data=$1 WHERE id=$2\',[JSON.stringify(state),\'main\']);const redirect=await get(\'/olivia-layout\');assert.equal(redirect.status,302);assert.equal(redirect.headers.get(\'location\'),\'/olivia-layout/\');const page=await get(\'/olivia-layout/\');assert.equal(page.status,200);assert.equal(page.headers.get(\'set-cookie\'),null);const html=await page.text();assert.ok(html.includes(\'src="layout-bootstrap.js"\'));assert.ok(html.includes(\'src="olivia-preview.js"\'));assert.ok(!html.includes(\'src="remote.js\'));for(const path of [...html.matchAll(/(?:src|href)="([^"#]+)"/g)].map(m=>m[1]).filter(p=>!p.startsWith(\'http\')&&!p.startsWith(\'/\')&&!p.startsWith(\'manifest\'))){const r=await get(\'/olivia-layout/\'+path);assert.equal(r.status,200,path);}const b=await get(\'/olivia-layout/layout-bootstrap.js\');assert.equal(b.status,200);assert.equal(b.headers.get(\'cache-control\'),\'no-store\');const text=await b.text();assert.ok(!text.includes(\'PrivateLiveSentinel\'));assert.ok(!text.includes(\'L_secret_live_record\'));const ctx={window:{}};vm.createContext(ctx);vm.runInContext(text,ctx);const boot=ctx.window.TL_BOOT;assert.equal(boot.layoutOnly,true);assert.equal(boot.preview,true);assert.equal(boot.state.me,\'u2\');assert.equal(boot.state.buildings.length,16);assert.equal(boot.state.leads.length,4);assert.ok(boot.state.leads.every(l=>l.first===\'Sample\'&&[\'u1\',\'u2\'].includes(l.rep)));assert.ok(boot.state.users.every(u=>u.email.endsWith(\'@example.invalid\')));for(const p of [\'bootstrap.js\',\'api/state\',\'api/export\',\'../config/users.json\',\'personal-access.html\',\'login.js\'])assert.notEqual((await get(\'/olivia-layout/\'+p)).status,200,p);assert.equal((await fetch(origin+\'/olivia-layout/layout-bootstrap.js\',{method:\'POST\'})).status,405);assert.equal((await get(\'/api/state\')).status,401);assert.equal((await get(\'/olivia-preview\')).status,302);assert.equal((await app.store.query(\'SELECT * FROM sessions\')).length,0);assert.deepEqual(JSON.parse((await app.store.query(\'SELECT data FROM app_state WHERE id=$1\',[\'main\']))[0].data),state);}finally{await app.close();rmSync(dir,{recursive:true,force:true});}});\n')
